#!/usr/bin/env node
/**
 * Alex's Bar Mitzvah — Send Save-the-Date Emails
 * ─────────────────────────────────────────────────
 * Sends save-the-date emails to all guests who haven't received one yet.
 * Uses data/guests.json (generated by import-guests.js).
 *
 * Usage:
 *   node scripts/send-save-the-date.js              # send to all unsent guests
 *   node scripts/send-save-the-date.js --dry-run    # preview without sending
 *   node scripts/send-save-the-date.js --email a@b.com  # single guest
 *   node scripts/send-save-the-date.js --resend     # re-send even if already sent
 */

'use strict';

const fs   = require('fs');
const path = require('path');

const args    = process.argv.slice(2);
const dryRun  = args.includes('--dry-run');
const resend  = args.includes('--resend');
const emailIdx = args.indexOf('--email');
const targetEmail = emailIdx >= 0 ? args[emailIdx + 1]?.toLowerCase() : null;

const DATA_DIR    = path.join(__dirname, '..', 'data');
const GUESTS_FILE = path.join(DATA_DIR, 'guests.json');
const CONFIG_FILE = path.join(DATA_DIR, 'config.json');

// ── Load config ───────────────────────────────────────────────────────────────
let cfg;
try { cfg = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8')); }
catch { console.error('\n  ✗  Cannot read data/config.json\n'); process.exit(1); }

if (!cfg.contact?.gmailUser || !cfg.contact?.gmailAppPassword ||
    cfg.contact.gmailAppPassword === 'REPLACE_WITH_YOUR_APP_PASSWORD') {
  console.error('\n  ✗  Gmail not configured.\n     Set gmailUser and gmailAppPassword in data/config.json\n');
  process.exit(1);
}

// ── Load email library ────────────────────────────────────────────────────────
let emailLib;
try { emailLib = require('../lib/emails.js'); }
catch { console.error('\n  ✗  Cannot load lib/emails.js. Run: npm install\n'); process.exit(1); }

// ── Load guests ───────────────────────────────────────────────────────────────
let guests;
try { guests = JSON.parse(fs.readFileSync(GUESTS_FILE, 'utf8')); }
catch { console.error('\n  ✗  Cannot read data/guests.json. Run: node scripts/import-guests.js\n'); process.exit(1); }

// ── Filter candidates ─────────────────────────────────────────────────────────
let targets = guests.filter(g => !g.isTest);

if (targetEmail) {
  targets = targets.filter(g => g.email === targetEmail);
  if (targets.length === 0) {
    console.error(`\n  ✗  No guest found with email: ${targetEmail}\n`);
    process.exit(1);
  }
}

if (!resend) {
  targets = targets.filter(g => !g.emails?.saveTheDate);
}

// ── Summary ───────────────────────────────────────────────────────────────────
console.log(`\n  📨 Save-the-Date Campaign`);
console.log(`  ─────────────────────────────────────────`);
console.log(`  Total guests:    ${guests.filter(g => !g.isTest).length}`);
console.log(`  Already sent:    ${guests.filter(g => !g.isTest && g.emails?.saveTheDate).length}`);
console.log(`  To send now:     ${targets.length}`);
if (dryRun) console.log(`\n  🔍 DRY RUN — no emails will be sent.`);
console.log('');

if (targets.length === 0) {
  console.log('  ✓  Nothing to send.\n');
  process.exit(0);
}

if (dryRun) {
  console.log('  Preview (first 10):');
  targets.slice(0, 10).forEach(g => {
    const greeting = emailLib.greetingName(g);
    console.log(`    ${greeting.padEnd(30)} → ${g.email}`);
  });
  console.log('');
  process.exit(0);
}

// ── Send ──────────────────────────────────────────────────────────────────────
const subject = cfg.saveTheDate?.subject || "Save the Date — Alex's Bar Mitzvah · August 22, 2026";

let sent = 0, failed = 0;

for (const guest of targets) {
  const html = emailLib.buildSaveTheDateHtml(guest, cfg);
  const text = emailLib.buildSaveTheDateText(guest, cfg);

  try {
    await emailLib.sendEmail({ to: guest.email, name: guest.name, subject, html, text }, cfg);
    // Update sent timestamp
    if (!guest.emails) guest.emails = {};
    guest.emails.saveTheDate = new Date().toISOString();
    guest.updated_at = new Date().toISOString();
    sent++;
    console.log(`  ✓  ${guest.name.padEnd(30)} → ${guest.email}`);
  } catch (err) {
    failed++;
    console.error(`  ✗  ${guest.name.padEnd(30)} → ${guest.email}  [${err.message}]`);
  }

  // Rate-limit: 1.2 s between sends (Gmail allows ~100/day via SMTP)
  if (targets.indexOf(guest) < targets.length - 1) {
    await new Promise(r => setTimeout(r, 1200));
  }
}

// ── Save updated guests.json ──────────────────────────────────────────────────
fs.writeFileSync(GUESTS_FILE, JSON.stringify(guests, null, 2), 'utf8');

console.log('');
console.log(`  ┌────────────────────────────────────────┐`);
console.log(`  │  Save-the-Date Results                 │`);
console.log(`  ├────────────────────────────────────────┤`);
console.log(`  │  Sent:      ${String(sent).padStart(4)}                   │`);
console.log(`  │  Failed:    ${String(failed).padStart(4)}                   │`);
console.log(`  └────────────────────────────────────────┘`);
console.log('');
console.log('  Next: node scripts/send-invites.js --dry-run\n');
